from api import orders


def test_checkout_logs_in_and_creates_order(monkeypatch):
    calls = []

    def fake_login(user, password, otp=None):
        calls.append((user, password, otp))
        return {"user": user, "token": "t"}

    monkeypatch.setattr(orders, "login", fake_login)
    monkeypatch.setattr(orders, "ORDERS", [])

    session, order = orders.checkout("alice", "pw", ["apple", "pear"], otp="123456")

    assert calls == [("alice", "pw", "123456")]
    assert session == {"user": "alice", "token": "t"}
    assert order == {"user": "alice", "items": ["apple", "pear"]}
    assert orders.ORDERS == [order]

